import httpx
from fastmcp import Server

def create_openapi_mcp_server(
    openapi_spec: dict,
    client: httpx.AsyncClient,
    server_name: str = "openapi-proxy"
) -> Server:
    """
    Create an MCP server from an OpenAPI 3.0 specification.

    Args:
        openapi_spec: OpenAPI 3.0 specification as a Python dict
        client: Configured httpx.AsyncClient with base URL set
        server_name: Name for the MCP server

    Returns:
        Configured fastmcp.Server instance
    """
    server = Server(server_name)

    paths = openapi_spec.get("paths", {})

    for path, path_item in paths.items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path.replace('/', '_')}")
            summary = operation.get("summary", "")
            description = operation.get("description", "")
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            # Build parameter schema
            param_schema = {
                "type": "object",
                "properties": {},
                "required": []
            }

            for param in parameters:
                param_name = param.get("name")
                param_in = param.get("in")  # path, query, header, cookie
                param_schema_def = param.get("schema", {})
                required = param.get("required", False)

                param_schema["properties"][param_name] = param_schema_def
                if required:
                    param_schema["required"].append(param_name)

            # Add request body if present
            if request_body:
                body_content = request_body.get("content", {})
                if "application/json" in body_content:
                    body_schema = body_content["application/json"].get("schema", {})
                    param_schema["properties"]["_request_body"] = body_schema
                    if request_body.get("required"):
                        param_schema["required"].append("_request_body")

            async def tool_handler(
                _path: str = path,
                _method: str = method,
                _params: dict = parameters,
                _request_body_schema: Optional[dict] = request_body,
                **kwargs: Any
            ) -> str:
                """Execute the OpenAPI operation via httpx client."""
                # Extract body if present
                body = None
                if "_request_body" in kwargs:
                    body = kwargs.pop("_request_body")

                # Prepare path with path parameters
                filled_path = _path
                for param in _params:
                    if param.get("in") == "path":
                        param_name = param.get("name")
                        if param_name in kwargs:
                            filled_path = filled_path.replace(f"{{{param_name}}}", str(kwargs.pop(param_name)))

                # Separate query and header parameters
                query_params = {}
                headers = {}
                for param in _params:
                    param_name = param.get("name")
                    if param_name in kwargs:
                        if param.get("in") == "query":
                            query_params[param_name] = kwargs.pop(param_name)
                        elif param.get("in") == "header":
                            headers[param_name] = kwargs.pop(param_name)

                # Make request
                response = await client.request(
                    _method.upper(),
                    filled_path,
                    json=body,
                    params=query_params,
                    headers=headers
                )

                return json.dumps({
                    "status": response.status_code,
                    "headers": dict(response.headers),
                    "body": response.text
                })

            # Register tool with server
            server.tool(
                name=operation_id,
                description=summary or description or f"{method.upper()} {path}",
                inputSchema=param_schema if param_schema["properties"] else {"type": "object"}
            )(tool_handler)

    return server


